import itertools

def check_m(m):
    # Necessary condition: m(m+1) must be divisible by 6
    if (m * (m + 1)) % 6 != 0:
        return False

    target_sum = m * (m + 1) // 6
    if target_sum <= 0:
        return False

    elements = set(range(1, m + 1))

    # Iterate through all possible subsets X (excluding empty set)
    all_subsets_X = []
    for k in range(1, m + 1):
        for subset in itertools.combinations(elements, k):
            all_subsets_X.append(set(subset))

    for X in all_subsets_X:
        sum_X = sum(X)

        if sum_X == target_sum:
            remaining_elements = elements - X

            # Check if a subset Y of remaining_elements sums to target_sum
            remaining_list = sorted(list(remaining_elements))

            # Iterate over all possible lengths k for Y (from 1 up to size of remaining_elements)
            for k in range(1, len(remaining_elements) + 1):
                for Y_tuple in itertools.combinations(remaining_list, k):
                    Y = set(Y_tuple)
                    sum_Y = sum(Y)

                    if sum_Y == target_sum:
                        # Found X and Y such that X intersect Y = empty, 
                        # and sums are correct.
                        return True

    return False

test_cases = [2, 3, 5, 6]
results = {}
for m in test_cases:
    results[m] = check_m(m)

print(results)
